(5761003, 838409, 108580, '<td valign="top">Well controlled exposure, reflector on petals and leaves subtle and accurate. Good DOF control.</td>', 'Well controlled exposure, reflector on petals and leaves subtle and accurate. Good DOF control.', '2009-12-09 05:03:39.000000', NULL, 1),
