(5761007, 837781, 108580, '<td valign="top">I''m at a loss for words. Let me try. This is so arty despite the huge negative space but the subject is looking IN THERE, so it leaves me feeling intrepid about what he/she is running from. Fab sillhouette. -1 for dust spot bottom middle. 9</td>', 'I''m at a loss for words. Let me try. This is so arty despite the huge negative space but the subject is looking IN THERE, so it leaves me feeling intrepid about what he/she is running from. Fab sillhouette. -1 for dust spot bottom middle. 9', '2009-12-09 05:06:22.000000', NULL, 1),
(5761010, 838242, 108580, '<td valign="top">Great Wide Angle bubbles. Unique in a sea of DPC bubbles. Perfect curve control and contrast. Oily blacks and crips whites. High marks.</td>', 'Great Wide Angle bubbles. Unique in a sea of DPC bubbles. Perfect curve control and contrast. Oily blacks and crips whites. High marks.', '2009-12-09 05:07:33.000000', NULL, 1),
