(5761563, 837486, 327, '<td valign="top">Simple but effective image. WTG</td>', 'Simple but effective image. WTG', '2009-12-09 11:42:05.000000', NULL, 1),
(5761570, 837508, 327, '<td valign="top">I like this ''grungie'' type shot. Very good.</td>', 'I like this ''grungie'' type shot. Very good.', '2009-12-09 11:44:21.000000', NULL, 1),
(5761571, 838399, 327, '<td valign="top">Pretty in pink.</td>', 'Pretty in pink.', '2009-12-09 11:45:01.000000', NULL, 1),
(5761573, 837854, 69368, '<td valign="top">like this. really nice shadow, nice idea-<br/>and they remind me on our dynamic duo :-)</td>', 'like this. really nice shadow, nice idea-and they remind me on our dynamic duo :-)', '2009-12-09 11:45:55.000000', NULL, 1),
(5761577, 838050, 69368, '<td valign="top">this is beautiful. keep my fingers cross, this will be in the top 5! good luck!</td>', 'this is beautiful. keep my fingers cross, this will be in the top 5! good luck!', '2009-12-09 11:47:22.000000', NULL, 1),
(5761600, 837679, 63503, '<td valign="top">Wonderful portrait!! I recognize this fellow (therefore not voting)</td>', 'Wonderful portrait!! I recognize this fellow (therefore not voting)', '2009-12-09 11:58:49.000000', NULL, 1),
(5761605, 837748, 112136, '<td valign="top">great shot</td>', 'great shot', '2009-12-09 12:03:06.000000', NULL, 1),
(5761606, 838206, 111625, '<td valign="top">I see what you were going for I just find the subject a cross between boring and creepy</td>', 'I see what you were going for I just find the subject a cross between boring and creepy', '2009-12-09 12:04:30.000000', NULL, 1),
(5761612, 837754, 112136, '<td valign="top">i like it so muchh..... an 8</td>', 'i like it so muchh..... an 8', '2009-12-09 12:09:47.000000', NULL, 1),
(5761615, 838334, 112136, '<td valign="top">wow this is beautiful....</td>', 'wow this is beautiful....', '2009-12-09 12:10:17.000000', NULL, 1),
(5761622, 838317, 105457, '<td valign="top">Nice atmosphere on the river bank, and such a great cloudy day to get this picture. <br/>I would probably boost the blues just for a more contrasty image, but the overall silhouette and the clouds are so well controlled, it all fits together.</td>', 'Nice atmosphere on the river bank, and such a great cloudy day to get this picture. I would probably boost the blues just for a more contrasty image, but the overall silhouette and the clouds are so well controlled, it all fits together.', '2009-12-09 12:15:03.000000', NULL, 1),
(5761646, 837682, 327, '<td valign="top">Background is blown out a little too much. Now the guy..well he''s a 10+!<br/>Not a bad entry all in all.</td>', 'Background is blown out a little too much. Now the guy..well he''s a 10+!Not a bad entry all in all.', '2009-12-09 12:40:44.000000', NULL, 1),
(5761648, 838195, 327, '<td valign="top">You have the right idea. I think the composition is lacking and that hurts the shot.</td>', 'You have the right idea. I think the composition is lacking and that hurts the shot.', '2009-12-09 12:41:45.000000', NULL, 1),
(5761652, 838335, 327, '<td valign="top">Fantastic lens! Very pretty.</td>', 'Fantastic lens! Very pretty.', '2009-12-09 12:43:17.000000', NULL, 1),
(5761653, 838050, 16488, '<td valign="top">The lower 2/3''s of this image is really lovely. The blown out sun, not so much.</td>', 'The lower 2/3''s of this image is really lovely. The blown out sun, not so much.', '2009-12-09 12:43:57.000000', NULL, 1),
(5761654, 837935, 327, '<td valign="top">This works! Love the silhouetted action.</td>', 'This works! Love the silhouetted action.', '2009-12-09 12:44:09.000000', NULL, 1),
(5761655, 838551, 16488, '<td valign="top">Nice concept but I think the light is a bit overdone.</td>', 'Nice concept but I think the light is a bit overdone.', '2009-12-09 12:44:26.000000', NULL, 1),
(5761690, 838091, 112136, '<td valign="top">fabulous shot, an 8</td>', 'fabulous shot, an 8', '2009-12-09 13:28:59.000000', NULL, 1),
(5761691, 838369, 112136, '<td valign="top">wonderful</td>', 'wonderful', '2009-12-09 13:29:24.000000', NULL, 1),
(5761692, 838494, 112136, '<td valign="top">fantastic shot.. u shud get a ribbon,</td>', 'fantastic shot.. u shud get a ribbon,', '2009-12-09 13:30:22.000000', NULL, 1),
(5761721, 838481, 56275, '<td valign="top">I like the bokeh and concept. Would be nice if the cup was more back-lit to create a glow.</td>', 'I like the bokeh and concept. Would be nice if the cup was more back-lit to create a glow.', '2009-12-09 13:58:01.000000', NULL, 1),
(5761722, 838062, 56275, '<td valign="top">Pretty sunset, but not sure what the gel leaves are contributing.. Screen is kind of distracting too.</td>', 'Pretty sunset, but not sure what the gel leaves are contributing.. Screen is kind of distracting too.', '2009-12-09 13:59:13.000000', NULL, 1),
(5761731, 838490, 56275, '<td valign="top">This would be awesome as an HDR. Love the composition. Just wish the boats in teh foreground were a little brighter.</td>', 'This would be awesome as an HDR. Love the composition. Just wish the boats in teh foreground were a little brighter.', '2009-12-09 14:05:16.000000', NULL, 1),
(5761733, 838477, 56275, '<td valign="top">Love the simplicity. 8</td>', 'Love the simplicity. 8', '2009-12-09 14:14:14.000000', NULL, 1),
(5761736, 838050, 42013, '<td valign="top">Here is a real eye catcher--for me anyway! :) If i could humbly suggest, cropping the sun out would take this to the top. It''s still a great photo, I just think the interplahy of shadows, tree tops, and baloon are the stars of the show. In this challenge, leaving the sun in was probably the safest route though. Good luck!</td>', 'Here is a real eye catcher--for me anyway! :) If i could humbly suggest, cropping the sun out would take this to the top. It''s still a great photo, I just think the interplahy of shadows, tree tops, and baloon are the stars of the show. In this challenge, leaving the sun in was probably the safest route though. Good luck!', '2009-12-09 14:18:03.000000', NULL, 1),
(5761737, 837453, 42013, '<td valign="top">Nicely done--quirky, love the intruding tree branch and the backlighting on the dog. The GG? bridge is a nice touch too. (that bridge sneaks into everything! ) :)</td>', 'Nicely done--quirky, love the intruding tree branch and the backlighting on the dog. The GG? bridge is a nice touch too. (that bridge sneaks into everything! ) :)', '2009-12-09 14:18:51.000000', NULL, 1),
(5761738, 838158, 42013, '<td valign="top">Bear? or is it Penny? :) I love the detail and the sense of wind in this picture. Good work!</td>', 'Bear? or is it Penny? :) I love the detail and the sense of wind in this picture. Good work!', '2009-12-09 14:19:36.000000', NULL, 1),
(5761744, 838334, 100393, '<td valign="top">I think you''ve got everything right here.</td>', 'I think you''ve got everything right here.', '2009-12-09 14:30:02.000000', NULL, 1),
(5761747, 838237, 100393, '<td valign="top">The lens flare is a wonderful feature in its own right. Good stuff.</td>', 'The lens flare is a wonderful feature in its own right. Good stuff.', '2009-12-09 14:32:02.000000', NULL, 1),
(5761750, 837407, 100393, '<td valign="top">Takes a little time but this is wonderful. I would''ve straightened it and cropped the wing(?) at the bottom - but lovely nonetheless.</td>', 'Takes a little time but this is wonderful. I would''ve straightened it and cropped the wing(?) at the bottom - but lovely nonetheless.', '2009-12-09 14:33:59.000000', NULL, 1),
(5761751, 838042, 100393, '<td valign="top">Another one that takes a little time to appreciate - it certainly is worth the wait!</td>', 'Another one that takes a little time to appreciate - it certainly is worth the wait!', '2009-12-09 14:35:25.000000', NULL, 1),
(5761753, 838345, 110041, '<td valign="top">Awesome clouds and a good capture.<br/> <br/>I''m more interested in the tree on the RHS with the sky behind to notice much else! <br/> <br/>As it is the LHS is a bit distracting.</td>', 'Awesome clouds and a good capture. I''m more interested in the tree on the RHS with the sky behind to notice much else!  As it is the LHS is a bit distracting.', '2009-12-09 14:37:42.000000', NULL, 1),
(5761754, 838163, 100393, '<td valign="top">Interesting effect.</td>', 'Interesting effect.', '2009-12-09 14:38:48.000000', NULL, 1),
(5761755, 837876, 110041, '<td valign="top">The flare around the vase is great especially with the bubbles in the water.<br/> <br/>In fact that''s more interesting than the flowers!<br/> <br/>Good shot though.</td>', 'The flare around the vase is great especially with the bubbles in the water. In fact that''s more interesting than the flowers! Good shot though.', '2009-12-09 14:40:18.000000', NULL, 1),
(5761756, 838500, 110041, '<td valign="top">Very well done, well controlled.</td>', 'Very well done, well controlled.', '2009-12-09 14:40:49.000000', NULL, 1),
(5761758, 837453, 110041, '<td valign="top">Too much tilt.</td>', 'Too much tilt.', '2009-12-09 14:43:38.000000', NULL, 1),
(5761760, 838378, 110041, '<td valign="top">Shame model is just off center and the light on the LHS wall makes it feel a little lop sided.<br/> <br/>Good moody shot though.</td>', 'Shame model is just off center and the light on the LHS wall makes it feel a little lop sided. Good moody shot though.', '2009-12-09 14:45:29.000000', NULL, 1),
(5761762, 837781, 110041, '<td valign="top">Not so keen on so much dead space.<br/> <br/>Good effort</td>', 'Not so keen on so much dead space. Good effort', '2009-12-09 14:47:00.000000', NULL, 1),
(5761764, 838050, 100393, '<td valign="top">This one hits a lot of the DPC buttons. I think it will do very well indeed.</td>', 'This one hits a lot of the DPC buttons. I think it will do very well indeed.', '2009-12-09 14:47:48.000000', NULL, 1),
(5761766, 838196, 110041, '<td valign="top">Good exposure, but treeline looks out of focus. I like the flaring</td>', 'Good exposure, but treeline looks out of focus. I like the flaring', '2009-12-09 14:48:38.000000', NULL, 1),
(5761777, 837741, 110041, '<td valign="top">Good scene but over processed for my liking.</td>', 'Good scene but over processed for my liking.', '2009-12-09 14:53:19.000000', NULL, 1),
(5761779, 838048, 110041, '<td valign="top">Tilt is good here.</td>', 'Tilt is good here.', '2009-12-09 14:53:42.000000', NULL, 1),
(5761781, 838448, 110041, '<td valign="top">Dirty lens?</td>', 'Dirty lens?', '2009-12-09 14:54:41.000000', NULL, 1),
(5761783, 838490, 110041, '<td valign="top">Sky looks very odd.</td>', 'Sky looks very odd.', '2009-12-09 14:56:26.000000', NULL, 1),
