(5763301, 837569, 57447, '<td valign="top">Very good presentation, processing, fits challenge well but seems to cross over more into graphic design than photography to me. Still a 7.</td>', 'Very good presentation, processing, fits challenge well but seems to cross over more into graphic design than photography to me. Still a 7.', '2009-12-10 17:42:50.000000', NULL, 1),
(5763302, 838259, 57447, '<td valign="top">Now, this is Contre-Jour to me.  Very nice!</td>', 'Now, this is Contre-Jour to me.  Very nice!', '2009-12-10 17:44:10.000000', NULL, 1),
(5763362, 838503, 112778, '<td valign="top">Horizon line is perfect. Brilliant shadows. Great source of light. Excellent capture overall.</td>', 'Horizon line is perfect. Brilliant shadows. Great source of light. Excellent capture overall.', '2009-12-10 19:43:27.000000', NULL, 1),
(5763373, 838170, 112778, '<td valign="top">I love the contrast between big and small. Somewhat mysterious and intriguing.</td>', 'I love the contrast between big and small. Somewhat mysterious and intriguing.', '2009-12-10 19:54:47.000000', NULL, 1),
(5763380, 838507, 112107, '<td valign="top">Great colors good composition but the horizon needs levelling.</td>', 'Great colors good composition but the horizon needs levelling.', '2009-12-10 19:59:49.000000', NULL, 1),
