(5763389, 838490, 112778, '<td valign="top">love the use of light, you can really see the depth in the sky and the movement of the water.</td>', 'love the use of light, you can really see the depth in the sky and the movement of the water.', '2009-12-10 20:07:14.000000', NULL, 1),
(5763391, 838104, 112778, '<td valign="top">The shadows give this photo complexity and elegance. Great use of light.</td>', 'The shadows give this photo complexity and elegance. Great use of light.', '2009-12-10 20:10:12.000000', NULL, 1),
(5763392, 838494, 112778, '<td valign="top">absolutely beautiful.</td>', 'absolutely beautiful.', '2009-12-10 20:11:04.000000', NULL, 1),
