(5763534, 837666, 111653, '<td valign="top">lol</td>', 'lol', '2009-12-10 23:39:35.000000', NULL, 1),
(5763655, 838499, 56579, '<td valign="top">I don''t like the white balance</td>', 'I don''t like the white balance', '2009-12-11 03:23:44.000000', NULL, 1),
(5763658, 838261, 94241, '<td valign="top">The top and bottom parts feels like two separate pictures to me, not really related to each other.  When this came up on my screen, the bottom part was "below the fold", scrolled off the bottom.  As far down as I could see was to the mountains.  Then I scrolled farther and I was surprised.  This is a stunningly beautiful image, and it impresses me a lot.  But in all honesty, I think I like it a bit better when it''s cropped short at the mountains, probably with a 4x5 frame.</td>', 'The top and bottom parts feels like two separate pictures to me, not really related to each other.  When this came up on my screen, the bottom part was "below the fold", scrolled off the bottom.  As far down as I could see was to the mountains.  Then I scrolled farther and I was surprised.  This is a stunningly beautiful image, and it impresses me a lot.  But in all honesty, I think I like it a bit better when it''s cropped short at the mountains, probably with a 4x5 frame.', '2009-12-11 03:30:06.000000', NULL, 1),
(5763663, 838399, 94241, '<td valign="top">So incredibly delicate.  My favorite of the contest.</td>', 'So incredibly delicate.  My favorite of the contest.', '2009-12-11 03:49:09.000000', NULL, 1),
(5763678, 838247, 37252, '<td valign="top">I really don''t care for the thick border, but the image is beautiful.</td>', 'I really don''t care for the thick border, but the image is beautiful.', '2009-12-11 04:10:02.000000', NULL, 1),
(5763682, 838455, 37252, '<td valign="top">sun-dog!</td>', 'sun-dog!', '2009-12-11 04:20:37.000000', NULL, 1),
