(5766011, 838503, 83313, '<td valign="top">Great detail and tones in a difficult lighting situation, Still, it comes off to me as a good snapshot. Fixing the tilt would have helped some.</td>', 'Great detail and tones in a difficult lighting situation, Still, it comes off to me as a good snapshot. Fixing the tilt would have helped some.', '2009-12-13 23:48:49.000000', NULL, 1),
(5766017, 837935, 83313, '<td valign="top">Great shot, but watch the compression. I can see obvious compression artifacts around the main subject in the foreground. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.</td>', 'Great shot, but watch the compression. I can see obvious compression artifacts around the main subject in the foreground. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.', '2009-12-13 23:55:30.000000', NULL, 1),
(5766020, 838195, 83313, '<td valign="top">Not coming off well for me, I''m afraid. Nothing is really standing out from this composition as the subject. It all just kind of blends in together.</td>', 'Not coming off well for me, I''m afraid. Nothing is really standing out from this composition as the subject. It all just kind of blends in together.', '2009-12-13 23:58:14.000000', NULL, 1),
(5766023, 837666, 83313, '<td valign="top">Run bear, run! She had the wedding planned and her children named before she even met you!</td>', 'Run bear, run! She had the wedding planned and her children named before she even met you!', '2009-12-14 00:01:04.000000', NULL, 1),
(5766029, 838051, 83313, '<td valign="top">A nice catch of a real scene, but it seems a snapshot to me. There is a lot of yellow from the incandescent lights. Setting the white balance differently could have helped some.</td>', 'A nice catch of a real scene, but it seems a snapshot to me. There is a lot of yellow from the incandescent lights. Setting the white balance differently could have helped some.', '2009-12-14 00:04:37.000000', NULL, 1),
(5766195, 838229, 66616, '<td valign="top">the dark area is like a graph showing how my investments have gone over the last few years! Nice image, great sky.</td>', 'the dark area is like a graph showing how my investments have gone over the last few years! Nice image, great sky.', '2009-12-14 03:08:43.000000', NULL, 1),
