(5766198, 838381, 66616, '<td valign="top">very apt for this time of the year!</td>', 'very apt for this time of the year!', '2009-12-14 03:12:48.000000', NULL, 1),
(5766221, 837204, 108580, '<td valign="top">Great shot and control of backlighting, PP technique also superb. Looks a bit blue-ish and some unavoidable highlights in bottom ferns.</td>', 'Great shot and control of backlighting, PP technique also superb. Looks a bit blue-ish and some unavoidable highlights in bottom ferns.', '2009-12-14 04:22:23.000000', NULL, 1),
(5766222, 838229, 108580, '<td valign="top">Stunning.</td>', 'Stunning.', '2009-12-14 04:22:43.000000', NULL, 1),
