(5766225, 837820, 108580, '<td valign="top">Awesome. I love the smooth orange sky. I like the odd wings blurred, others might not.</td>', 'Awesome. I love the smooth orange sky. I like the odd wings blurred, others might not.', '2009-12-14 04:24:32.000000', NULL, 1),
(5766228, 838477, 108580, '<td valign="top">Lovely shot, tree a bit OOF, sky and silhouette appealing. Some grain visible but not annoying.</td>', 'Lovely shot, tree a bit OOF, sky and silhouette appealing. Some grain visible but not annoying.', '2009-12-14 04:25:42.000000', NULL, 1),
(5766230, 837324, 108580, '<td valign="top">Excellent "street" capture and exp control, good attention to composure.  Human shadows add appeal. Arty and unusual for DPC, WD!</td>', 'Excellent "street" capture and exp control, good attention to composure.  Human shadows add appeal. Arty and unusual for DPC, WD!', '2009-12-14 04:26:49.000000', NULL, 1),
(5766232, 838478, 108580, '<td valign="top">Beautiful portrait, nice emotion on model, good fill-in. Spoiled a bit by the cupboard/shelf right hand side.</td>', 'Beautiful portrait, nice emotion on model, good fill-in. Spoiled a bit by the cupboard/shelf right hand side.', '2009-12-14 04:28:41.000000', NULL, 1),
(5766235, 838373, 108580, '<td valign="top">Nice shot, but I think a bit of hassle with curves around the light source obscuring elements of the subject and too much USM.</td>', 'Nice shot, but I think a bit of hassle with curves around the light source obscuring elements of the subject and too much USM.', '2009-12-14 04:31:18.000000', NULL, 1),
(5766238, 837566, 108580, '<td valign="top">Great shot, silhouette, colours, horison. I like the gradations/halo but others might not.</td>', 'Great shot, silhouette, colours, horison. I like the gradations/halo but others might not.', '2009-12-14 04:32:25.000000', NULL, 1),
(5766240, 838194, 108580, '<td valign="top">Lovely natural shot. No ecidence of Topax, HDR etc, good for you. Subtle and appealing. 9</td>', 'Lovely natural shot. No ecidence of Topax, HDR etc, good for you. Subtle and appealing. 9', '2009-12-14 04:33:39.000000', NULL, 1),
(5766263, 838402, 105457, '<td valign="top">This is just great!<br/>Great shape on the light, good fill on his face, superb in every detail. Congratulations!</td>', 'This is just great!Great shape on the light, good fill on his face, superb in every detail. Congratulations!', '2009-12-14 05:14:08.000000', NULL, 1),
(5766264, 838049, 105457, '<td valign="top">Wow, a long exposure with such control on the light, amazing.<br/>Magnificent capture!</td>', 'Wow, a long exposure with such control on the light, amazing.Magnificent capture!', '2009-12-14 05:14:51.000000', NULL, 1),
(5766265, 837741, 105457, '<td valign="top">Just love the dynamic range on this photo. The details are so intensive, and the HDR(?) is so well done. Great star effect, and nice grain.</td>', 'Just love the dynamic range on this photo. The details are so intensive, and the HDR(?) is so well done. Great star effect, and nice grain.', '2009-12-14 05:15:41.000000', NULL, 1),
(5766266, 838334, 105457, '<td valign="top">I really like the reflections on this one.<br/>The way you retained the colour on the pond flowers is just perfect.</td>', 'I really like the reflections on this one.The way you retained the colour on the pond flowers is just perfect.', '2009-12-14 05:16:24.000000', NULL, 1),
(5766271, 838335, 105457, '<td valign="top">Ultra Wide Angle :)<br/>Great shot from St. Peter''s Square, and it is fantastic the way you retained the details on the foreground.</td>', 'Ultra Wide Angle :)Great shot from St. Peter''s Square, and it is fantastic the way you retained the details on the foreground.', '2009-12-14 05:24:18.000000', NULL, 1),
(5766274, 838050, 105457, '<td valign="top">I love the gradation on the bottom, it is just beautiful.<br/>Good control on the sun directly in front, and great tones all around.</td>', 'I love the gradation on the bottom, it is just beautiful.Good control on the sun directly in front, and great tones all around.', '2009-12-14 05:27:21.000000', NULL, 1),
(5766275, 838494, 105457, '<td valign="top">Very nice balance between all. Would have liked it better if it was not centred, but still a 9 from me.</td>', 'Very nice balance between all. Would have liked it better if it was not centred, but still a 9 from me.', '2009-12-14 05:28:18.000000', NULL, 1),
(5766277, 837935, 105457, '<td valign="top">Great composition, nice choice for B&amp;W.</td>', 'Great composition, nice choice for B&W.', '2009-12-14 05:29:18.000000', NULL, 1),
