(5767605, 838237, 108580, '<td valign="top">Nice sunburst and appealing green flare. Just enough detail in the shadows to add interest and make my eye move around.</td>', 'Nice sunburst and appealing green flare. Just enough detail in the shadows to add interest and make my eye move around.', '2009-12-15 02:19:42.000000', NULL, 1),
(5767649, 838157, 105457, '<td valign="top">Wonderful tones, and a very appealing silhouette.<br/>It''s just a little pixelized on the edges, but that''s because of the resizing.</td>', 'Wonderful tones, and a very appealing silhouette.It''s just a little pixelized on the edges, but that''s because of the resizing.', '2009-12-15 05:11:27.000000', NULL, 1),
(5767650, 838017, 105457, '<td valign="top">Great capture, even with the flare above the dog.</td>', 'Great capture, even with the flare above the dog.', '2009-12-15 05:11:57.000000', NULL, 1),
(5767651, 837795, 105457, '<td valign="top">Great atmosphere, and beautiful shadows here. The horizon seems a bit crooked, but it does not impact the photo negatively.</td>', 'Great atmosphere, and beautiful shadows here. The horizon seems a bit crooked, but it does not impact the photo negatively.', '2009-12-15 05:12:58.000000', NULL, 1),
(5767652, 838230, 105457, '<td valign="top">Brutal negative space :) nice gradient on the sky, and nice placing with the sun.</td>', 'Brutal negative space :) nice gradient on the sky, and nice placing with the sun.', '2009-12-15 05:13:50.000000', NULL, 1),
(5767655, 837781, 105457, '<td valign="top">Great framing. Not exactly against the light as many others are, but a very good use of composition.</td>', 'Great framing. Not exactly against the light as many others are, but a very good use of composition.', '2009-12-15 05:35:47.000000', NULL, 1),
(5767656, 837204, 105457, '<td valign="top">Mystical woods, great saturation.</td>', 'Mystical woods, great saturation.', '2009-12-15 05:36:39.000000', NULL, 1),
(5767657, 837539, 105457, '<td valign="top">The tilting does not work very much for me, but the photo is very well controlled, and great clarity and tones.</td>', 'The tilting does not work very much for me, but the photo is very well controlled, and great clarity and tones.', '2009-12-15 05:37:20.000000', NULL, 1),
(5767658, 837754, 105457, '<td valign="top">City night lights, very moody, very saturated. Good placing and framing.</td>', 'City night lights, very moody, very saturated. Good placing and framing.', '2009-12-15 05:38:06.000000', NULL, 1),
(5767660, 837508, 63716, '<td valign="top">Great photo, but I''m struggling to see how it interprets the theme</td>', 'Great photo, but I''m struggling to see how it interprets the theme', '2009-12-15 05:47:10.000000', NULL, 1),
(5767661, 837854, 55221, '<td valign="top">I love the vibrancy of this photograph. I might have chosen a different title, though, as the feel of the photograph seems rather quiet.</td>', 'I love the vibrancy of this photograph. I might have chosen a different title, though, as the feel of the photograph seems rather quiet.', '2009-12-15 05:47:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5767662, 838490, 55221, '<td valign="top">This looks just a bit too edited. But, perhaps that''s just me.</td>', 'This looks just a bit too edited. But, perhaps that''s just me.', '2009-12-15 05:48:34.000000', NULL, 1),
(5767674, 837205, 108580, '<td valign="top">Not sure this meets the challenge, lighting is from the subject, technically OK but my understanding should be from behind or side of subject.</td>', 'Not sure this meets the challenge, lighting is from the subject, technically OK but my understanding should be from behind or side of subject.', '2009-12-15 06:43:06.000000', NULL, 1),
(5767683, 838170, 105457, '<td valign="top">I would have liked the front to have a bit more light, but I like the composition very much, good use of the rules here.</td>', 'I would have liked the front to have a bit more light, but I like the composition very much, good use of the rules here.', '2009-12-15 07:17:22.000000', NULL, 1),
(5767684, 837569, 105457, '<td valign="top">Ok-kaay...You got high marks from me for not being able to find out what it is.<br/>Love the colours, smoothness and lighting.</td>', 'Ok-kaay...You got high marks from me for not being able to find out what it is.Love the colours, smoothness and lighting.', '2009-12-15 07:18:08.000000', NULL, 1),
(5767685, 838247, 105457, '<td valign="top">Great lighting, would have liked it better without the borders.</td>', 'Great lighting, would have liked it better without the borders.', '2009-12-15 07:18:48.000000', NULL, 1),
(5767686, 837929, 105457, '<td valign="top">Great strobist photo here.</td>', 'Great strobist photo here.', '2009-12-15 07:19:00.000000', NULL, 1),
(5767687, 838381, 105457, '<td valign="top">Not a very contre-jour photo, but the bokeh is very nice and the texture is great!</td>', 'Not a very contre-jour photo, but the bokeh is very nice and the texture is great!', '2009-12-15 07:19:31.000000', NULL, 1),
(5767688, 838507, 105457, '<td valign="top">Postcard photo, very appealing. Could have the whole palm tree in the photo though.</td>', 'Postcard photo, very appealing. Could have the whole palm tree in the photo though.', '2009-12-15 07:20:10.000000', NULL, 1),
(5767690, 837534, 105457, '<td valign="top">GREAT dof, very well controlled and perfectly lit.</td>', 'GREAT dof, very well controlled and perfectly lit.', '2009-12-15 07:20:30.000000', NULL, 1),
(5767727, 838399, 105457, '<td valign="top">Very good transparency, although you lost a lot of details in the middle.</td>', 'Very good transparency, although you lost a lot of details in the middle.', '2009-12-15 08:20:53.000000', NULL, 1),
(5767759, 837684, 105457, '<td valign="top">Perfect silhouette. Could use a bit more noise reduction.</td>', 'Perfect silhouette. Could use a bit more noise reduction.', '2009-12-15 08:55:54.000000', NULL, 1),
(5767760, 838503, 107027, '<td valign="top">Nice shot, I really like the colors.  It looks like its going to rain the next day.  Composition is good and the light behind the tree looks great.  I like the shadow that it casts of the tree which goes towards the viewer and straight out of the image!</td>', 'Nice shot, I really like the colors.  It looks like its going to rain the next day.  Composition is good and the light behind the tree looks great.  I like the shadow that it casts of the tree which goes towards the viewer and straight out of the image!', '2009-12-15 08:57:08.000000', NULL, 1),
(5767763, 838373, 105457, '<td valign="top">Good idea, but you lost very much on the compression of the file, some lines are very edgy.</td>', 'Good idea, but you lost very much on the compression of the file, some lines are very edgy.', '2009-12-15 09:07:29.000000', NULL, 1),
(5767803, 838051, 108580, '<td valign="top">I like impromptu captures, subjects are unaware of the camera and more natural. Lights appear above them, not behind them? Edit, Oh wait, captured from a mirror :)</td>', 'I like impromptu captures, subjects are unaware of the camera and more natural. Lights appear above them, not behind them? Edit, Oh wait, captured from a mirror :)', '2009-12-15 10:27:55.000000', NULL, 1),
(5767804, 838241, 108580, '<td valign="top">Good exp control of your camera pre PS PP. Her look/emotion is a bit contrived. Skin tones a bit red. Too much wine? :) Meets challenge</td>', 'Good exp control of your camera pre PS PP. Her look/emotion is a bit contrived. Skin tones a bit red. Too much wine? :) Meets challenge', '2009-12-15 10:28:36.000000', NULL, 1),
(5767813, 837518, 108580, '<td valign="top">Image meets challenge. Great sunburst, nice and close shot. Good exposure control in the shadow area. Colours and contrast somewhat weak.</td>', 'Image meets challenge. Great sunburst, nice and close shot. Good exposure control in the shadow area. Colours and contrast somewhat weak.', '2009-12-15 10:58:05.000000', NULL, 1),
(5767872, 838468, 108580, '<td valign="top">Arty and appealing. I like the dead space between the objects. I might have raised the bottom three glass objects above the line of the window frame somehow, perhaps with a piece of wood wrapped in a dark cloth.</td>', 'Arty and appealing. I like the dead space between the objects. I might have raised the bottom three glass objects above the line of the window frame somehow, perhaps with a piece of wood wrapped in a dark cloth.', '2009-12-15 12:26:06.000000', NULL, 1),
(5767875, 838345, 108580, '<td valign="top">Stunning. Revisited this shot just before rollover. Bumped 2 more points.</td>', 'Stunning. Revisited this shot just before rollover. Bumped 2 more points.', '2009-12-15 12:29:31.000000', NULL, 1),
(5767942, 837684, 108580, '<td valign="top">Image is nicely composed and sky colour lovely but Toucan OOF. Pushing the curves here to get a little detail on the statue left you with a lot of grain in the sky. Still a nice shot.</td>', 'Image is nicely composed and sky colour lovely but Toucan OOF. Pushing the curves here to get a little detail on the statue left you with a lot of grain in the sky. Still a nice shot.', '2009-12-15 13:35:14.000000', NULL, 1),
