(5768005, 838378, 101668, '<td valign="top">Very good and original.</td>', 'Very good and original.', '2009-12-15 14:48:37.000000', NULL, 1),
(5768022, 838159, 30049, '<td valign="top">I like how there''s just enough back light to illuminate the shirt for some detail.  Nicely done.</td>', 'I like how there''s just enough back light to illuminate the shirt for some detail.  Nicely done.', '2009-12-15 15:49:47.000000', NULL, 1),
(5768023, 838402, 30049, '<td valign="top">This is a very cool shot.  Great location, and very good control of the exposure in this environment.  Nice!</td>', 'This is a very cool shot.  Great location, and very good control of the exposure in this environment.  Nice!', '2009-12-15 15:50:29.000000', NULL, 1),
(5768024, 837795, 30049, '<td valign="top">Good timing on the setting sun.  It moves dang fast at that point, doesn''t it.  :-)  A fun scene.  Good luck.</td>', 'Good timing on the setting sun.  It moves dang fast at that point, doesn''t it.  :-)  A fun scene.  Good luck.', '2009-12-15 15:51:21.000000', NULL, 1),
(5768025, 837748, 30049, '<td valign="top">Lovely location.  I like the backlit spray in the upper-left.</td>', 'Lovely location.  I like the backlit spray in the upper-left.', '2009-12-15 15:51:58.000000', NULL, 1),
(5768026, 838364, 30049, '<td valign="top">Guy''s shooting the wrong way!  :-)  Just kidding.  This is a nice capture you have here.  Good luck.</td>', 'Guy''s shooting the wrong way!  :-)  Just kidding.  This is a nice capture you have here.  Good luck.', '2009-12-15 15:53:08.000000', NULL, 1),
(5768027, 837927, 30049, '<td valign="top">I love highlihgted sunbeams like this.  I scored this earlier and gave it a good mark (which isn''t changing), but seeing it the second time around while commenting I kind of wish there was something a little more exciting going on in the background.  Just an observation.  Overall, a very nice catch.  Good luck in the challenge.</td>', 'I love highlihgted sunbeams like this.  I scored this earlier and gave it a good mark (which isn''t changing), but seeing it the second time around while commenting I kind of wish there was something a little more exciting going on in the background.  Just an observation.  Overall, a very nice catch.  Good luck in the challenge.', '2009-12-15 15:55:14.000000', NULL, 1),
