(5770206, 838143, 30861, '<td valign="top">Man, it''s been forever since I heard mention of the beagle boys, scrooge!</td>', 'Man, it''s been forever since I heard mention of the beagle boys, scrooge!', '2009-12-17 10:52:05.000000', NULL, 0),
(5770252, 838158, 70661, '<td valign="top">Beautiful!!!!</td>', 'Beautiful!!!!', '2009-12-17 12:19:42.000000', NULL, 0),
